    public void handleCancelOrders(Client client, Map<String, Object> message)
    {
        //
        //     {
        //         "event": "canceled-orders",
        //         "data": {
        //             "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96",
        //             "ordersDeleted": [
        //                 { "id": "cab25117-47ce-4991-98d3-3a334afbc6a0", "status": "cancelled" }
        //             ],
        //             "ordersNotDeletedReasons": [
        //                 {
        //                     "id": "a00ea616-aed4-44eb-9e05-b55c475e39d9",
        //                     "reason": "The order with ID a00ea616-aed4-44eb-9e05-b55c475e39d9 was not found",
        //                     "error": { "code": "ORDER_NOT_FOUND", "message": "The order with ID a00ea616-aed4-44eb-9e05-b55c475e39d9 was not found" }
        //                 }
        //             ]
        //         }
        //     }
        //
        Map<String, Object> data = this.safeDict(message, "data", new HashMap<String, Object>() {{}});
        List<Object> deleted = this.safeList(data, "ordersDeleted", new ArrayList<Object>(Arrays.asList()));
        List<Object> notDeleted = this.safeList(data, "ordersNotDeletedReasons", new ArrayList<Object>(Arrays.asList()));
        List<Object> orders = new ArrayList<Object>(Arrays.asList());
        for (var i = 0; i < deleted.size(); i++)
        {
            Object entry = (deleted == null || i < 0 || i >= deleted.size() ? null : deleted.get(i));
            ((List<Object>)orders).add(this.safeOrder(new HashMap<String, Object>() {{
                put( "info", entry );
                put( "id", Bit2me.this.safeString(entry, "id") );
                put( "status", Bit2me.this.parseOrderStatus(Bit2me.this.safeString(entry, "status")) );
            }}, (Map<String, Object>) null));
        }
        for (var i = 0; i < notDeleted.size(); i++)
        {
            Object entry = (notDeleted == null || i < 0 || i >= notDeleted.size() ? null : notDeleted.get(i));
            ((List<Object>)orders).add(this.safeOrder(new HashMap<String, Object>() {{
                put( "info", entry );
                put( "id", Bit2me.this.safeString(entry, "id") );
                put( "status", null );
            }}, (Map<String, Object>) null));
        }
        this.settleRequest(client, "canceled-orders", orders, (Object) null);
    }

